import math

def sum_squares(lst):
    def round_number(num):
        if num >= 0:
            return math.ceil(num)
        else:
            return math.floor(num)

    def square_number(num):
        return num ** 2

    rounded_lst = [round_number(num) for num in lst]
    squared_lst = [square_number(num) for num in rounded_lst]

    return sum(squared_lst)

