def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    planet_order = {planet: index for index, planet in enumerate(planets)}

    if planet1 not in planet_order or planet2 not in planet_order:
        return ()

    start_index = planet_order[planet1]
    end_index = planet_order[planet2]

    if start_index < end_index:
        return tuple(planet for planet in planets[start_index+1:end_index])
    else:
        return tuple(planet for planet in planets[end_index+1:start_index][::-1])
